import java.nio.file.Path;
import java.nio.file.Files;
import java.io.IOException;

public class PathExample {
    public static void main(String[] args) throws IOException {
        // Modern way (Java 11+)
        Path configPath = Path.of("config", "application.properties");

        // Older way (Java 7+) - still valid
        Path logPath = Path.of("logs/output.txt");

        System.out.println("Config path: " + configPath);
        System.out.println("Absolute: " + configPath.toAbsolutePath());
        System.out.println("File name: " + configPath.getFileName());

        // Check if file exists using Files utility
        if (Files.exists(configPath)) {
            long size = Files.size(configPath);
            System.out.println("Size: " + size + " bytes");
        }
    }
}

import java.nio.file.*;
import java.io.IOException;
import java.util.List;

public class FilesDemo {
    public static void main(String[] args) throws IOException {
        Path configDir = Path.of("config");
        Path configFile = configDir.resolve("app.properties");

        // Create directory if it doesn't exist
        Files.createDirectories(configDir);

        // Write configuration
        String config = "app.name=MyApp\napp.version=1.0";
        Files.writeString(configFile, config);

        // Read entire file as String (Java 11+)
        String content = Files.readString(configFile);

        // Read as lines for processing
        List<String> lines = Files.readAllLines(configFile);
        lines.forEach(System.out::println);

        // Copy to backup location
        Path backup = Path.of("backup/app.properties");
        Files.createDirectories(backup.getParent());
        Files.copy(configFile, backup, StandardCopyOption.REPLACE_EXISTING);

        // Check properties
        System.out.println("Size: " + Files.size(configFile) + " bytes");
        System.out.println("Is regular file: " + Files.isRegularFile(configFile));
    }
}

import java.nio.file.Path;

public class PathManipulation {
    public static void main(String[] args) {
        Path baseDir = Path.of("project");
        Path configDir = baseDir.resolve("config");
        Path configFile = configDir.resolve("app.properties");

        System.out.println("Config file: " + configFile);
        // Output: project/config/app.properties

        // Relativize: find path from config to logs
        Path logsDir = baseDir.resolve("logs");
        Path relativePath = configDir.relativize(logsDir);
        System.out.println("From config to logs: " + relativePath);
        // Output: ../logs

        // Normalize: clean up redundant segments
        Path messy = Path.of("project/config/../logs/./output.txt");
        Path clean = messy.normalize();
        System.out.println("Normalized: " + clean);
        // Output: project/logs/output.txt

        // Combining operations
        Path docPath = Path.of("docs").resolve("../images/logo.png").normalize();
        System.out.println("Doc path: " + docPath);
        // Output: images/logo.png
    }
}

import java.nio.file.*;
import java.io.IOException;
import static java.nio.file.StandardWatchEventKinds.*;

public class ConfigWatcher {
    public static void main(String[] args) throws IOException, InterruptedException {
        Path configDir = Path.of("config");
        Files.createDirectories(configDir);

        // Create WatchService and register directory
        WatchService watchService = FileSystems.getDefault().newWatchService();
        configDir.register(watchService, ENTRY_CREATE, ENTRY_MODIFY, ENTRY_DELETE);

        System.out.println("Watching " + configDir + " for changes...");

        while (true) {
            WatchKey key = watchService.take(); // Blocks until event occurs

            for (WatchEvent<?> event : key.pollEvents()) {
                WatchEvent.Kind<?> kind = event.kind();
                Path fileName = (Path) event.context();

                System.out.println(kind.name() + ": " + fileName);

                if (kind == ENTRY_MODIFY && fileName.toString().endsWith(".properties")) {
                    System.out.println("Config file changed! Reloading...");
                    // Reload configuration logic here
                }
            }

            boolean valid = key.reset(); // Reset key to receive further events
            if (!valid) break; // Directory no longer accessible
        }
    }
}
